#!/usr/bin/env python3
"""Rerunnable public-source patch for Linux/Windows automatic downloads. No phone access."""
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
FILES = {'kyf37-installer/kyf37_resources.py': '"""Download public tools and release assets; never handles signing keys."""\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport shutil\nimport stat\nimport tempfile\nimport urllib.request\nimport zipfile\n\nRELEASE_API = \'https://api.github.com/repos/PabloTToledano/kyf37_rom/releases/latest\'\n\n\ndef download(url, destination, expected=None):\n    if not url.startswith(\'https://\'):\n        raise ValueError(\'Downloads require HTTPS\')\n    destination = Path(destination)\n    destination.parent.mkdir(parents=True, exist_ok=True)\n    if expected and destination.is_file() and sha256(destination) == expected:\n        return destination\n    temporary = destination.with_name(destination.name + \'.download\')\n    try:\n        request = urllib.request.Request(url, headers={\'User-Agent\': \'kyf37-installer\'})\n        with urllib.request.urlopen(request, timeout=60) as response, temporary.open(\'wb\') as out:\n            if not response.url.startswith(\'https://\'):\n                raise ValueError(\'Insecure download redirect\')\n            shutil.copyfileobj(response, out, 8 << 20)\n        if expected and sha256(temporary) != expected:\n            raise ValueError(\'Downloaded file failed SHA-256 verification\')\n        temporary.replace(destination)\n    finally:\n        temporary.unlink(missing_ok=True)\n    return destination\n\n\ndef sha256(path):\n    h = hashlib.sha256()\n    with open(path, \'rb\') as f:\n        for block in iter(lambda: f.read(8 << 20), b\'\'):\n            h.update(block)\n    return h.hexdigest()\n\n\ndef platform_tools(directory):\n    system = platform.system()\n    if system not in (\'Linux\', \'Windows\'):\n        raise RuntimeError(\'Automatic platform-tools download supports Linux and Windows\')\n    if platform.machine().lower() not in (\'amd64\', \'x86_64\'):\n        raise RuntimeError(\'Automatic platform-tools requires x86-64; supply a compatible ADB on PATH\')\n    directory = Path(directory)\n    target = directory / \'platform-tools\'\n    executable = target / (\'adb.exe\' if system == \'Windows\' else \'adb\')\n    if executable.is_file():\n        return str(executable)\n    archive = download(\'https://dl.google.com/android/repository/platform-tools-latest-\' +\n                       (\'windows\' if system == \'Windows\' else \'linux\') + \'.zip\', directory / \'platform-tools.zip\')\n    with tempfile.TemporaryDirectory(dir=directory) as temporary:\n        stage = Path(temporary)\n        with zipfile.ZipFile(archive) as z:\n            for info in z.infolist():\n                path = stage / info.filename\n                if not path.resolve().is_relative_to(stage.resolve()):\n                    raise ValueError(\'Unsafe platform-tools archive path\')\n                z.extract(info, stage)\n        staged = stage / \'platform-tools\'\n        adb = staged / executable.name\n        if not adb.is_file():\n            raise ValueError(\'Downloaded platform-tools has no adb\')\n        if system == \'Linux\':\n            for name in (\'adb\', \'fastboot\'):\n                file = staged / name\n                if file.exists():\n                    file.chmod(file.stat().st_mode | stat.S_IXUSR)\n        # Only a complete extracted directory becomes available to later runs.\n        if target.exists():\n            raise RuntimeError(\'Incomplete platform-tools directory; preserve or move it before retrying\')\n        staged.replace(target)\n    return str(executable)\n\n\ndef release_rom(directory, url=None, digest=None):\n    if url:\n        if not digest or len(digest) != 64 or any(c not in \'0123456789abcdef\' for c in digest):\n            raise ValueError(\'--rom-url requires --rom-sha256 with the published SHA-256 digest\')\n        return download(url, Path(directory) / (\'rom-\' + digest + \'.zip\'), digest)\n    request = urllib.request.Request(RELEASE_API, headers={\'User-Agent\': \'kyf37-installer\'})\n    with urllib.request.urlopen(request, timeout=60) as response:\n        release = json.load(response)\n    candidates = [a for a in release.get(\'assets\', [])\n                  if a[\'name\'].endswith(\'.zip\') and \'twrp\' in a[\'name\'] and \'android11\' in a[\'name\']]\n    if len(candidates) != 1:\n        raise RuntimeError(\'Latest release has no unique Android 11 TWRP ROM. Use --rom FILE or --rom-url URL --rom-sha256 HASH; no other Android version will be substituted.\')\n    asset = candidates[0]\n    digest = asset.get(\'digest\', \'\')\n    if not digest or not digest.startswith(\'sha256:\'):\n        raise RuntimeError(\'Release asset lacks a SHA-256 digest; supply --rom-url and --rom-sha256\')\n    return release_rom(directory, asset[\'browser_download_url\'], digest.split(\':\', 1)[1])\n', 'kyf37-installer/bootstrap.py': '#!/usr/bin/env python3\n"""Repair or create a local Python environment, then run the installer."""\nimport hashlib\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\n\nHERE = Path(__file__).resolve().parent\nsys.path.insert(0, str(HERE))\nfrom kyf37_resources import download\n\n\ndef main():\n    if sys.version_info < (3, 9):\n        raise SystemExit(\'Python 3.9 or newer is required\')\n    environment = HERE / \'.venv\'\n    python = environment / (\'Scripts/python.exe\' if os.name == \'nt\' else \'bin/python\')\n    if not python.is_file():\n        result = subprocess.run([sys.executable, \'-m\', \'venv\', \'--without-pip\', str(environment)])\n        if result.returncode:\n            virtualenv = download(\'https://bootstrap.pypa.io/virtualenv.pyz\', HERE / \'.downloads/virtualenv.pyz\')\n            subprocess.run([sys.executable, str(virtualenv), str(environment)], check=True)\n    if subprocess.run([str(python), \'-m\', \'pip\', \'--version\'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode:\n        getpip = download(\'https://bootstrap.pypa.io/get-pip.py\', HERE / \'.downloads/get-pip.py\')\n        subprocess.run([str(python), str(getpip)], check=True)\n    requirements = HERE / \'requirements.txt\'\n    fingerprint = hashlib.sha256(requirements.read_bytes() + sys.version.encode()).hexdigest()\n    stamp = environment / \'requirements.sha256\'\n    ready = subprocess.run([str(python), \'-c\', \'import cryptography, usb, libusb_package\'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0\n    if not ready or not stamp.exists() or stamp.read_text() != fingerprint:\n        subprocess.run([str(python), \'-m\', \'pip\', \'install\', \'-r\', str(requirements)], check=True)\n        stamp.write_text(fingerprint)\n    return subprocess.call([str(python), str(HERE / \'kyf37_installer.py\'), *sys.argv[1:]])\n\n\nif __name__ == \'__main__\':\n    sys.exit(main())\n', 'kyf37-installer/install.sh': '#!/usr/bin/env bash\n# Linux launcher: keep downloads and dependencies local to the installer.\nset -euo pipefail\ncd "$(dirname "$0")"\nif ! command -v python3 >/dev/null || ! python3 -c \'import sys; sys.exit(sys.version_info < (3, 9))\'; then\n  if [[ ! -x .python/python/bin/python3 ]]; then\n    echo \'Downloading a private Python runtime...\'\n    mkdir -p .downloads .python\n    fetch() {\n      if command -v curl >/dev/null; then curl --fail --location --proto \'=https\' --tlsv1.2 "$1" -o "$2";\n      elif command -v wget >/dev/null; then wget --https-only "$1" -O "$2";\n      else echo \'Install curl or wget to download Python.\' >&2; return 1; fi\n    }\n    case "$(uname -m)" in\n      x86_64) arch=x86_64;;\n      aarch64) arch=aarch64;;\n      *) echo \'Unsupported CPU; install Python 3.9+ manually.\' >&2; exit 1;;\n    esac\n    fetch https://api.github.com/repos/astral-sh/python-build-standalone/releases/latest .downloads/python-release.json\n    url=$(sed -n \'s/.*"browser_download_url": "\\([^"]*\\)".*/\\1/p\' .downloads/python-release.json | sed -n "/cpython-3\\.12\\..*${arch}-unknown-linux-gnu-install_only\\.tar\\.gz$/p" | head -n 1)\n    [[ -n "$url" ]] || { echo \'No compatible Python download; install Python 3.9+ manually.\' >&2; exit 1; }\n    fetch "$url" .downloads/python.tar.gz.partial\n    tar -xzf .downloads/python.tar.gz.partial -C .python\n  fi\n  exec .python/python/bin/python3 bootstrap.py "$@"\nfi\nexec python3 bootstrap.py "$@"\n', 'kyf37-installer/install.ps1': '# Windows launcher. Missing Python is installed privately, without changing PATH.\n$ErrorActionPreference = \'Stop\'\nSet-Location $PSScriptRoot\n$python = $null\nforeach ($name in @(\'py\', \'python\')) {\n    $candidate = Get-Command $name -ErrorAction SilentlyContinue\n    if ($candidate) {\n        $prefix = @()\n        if ($name -eq \'py\') { $prefix = @(\'-3\') }\n        & $candidate.Source @prefix -c \'import sys; sys.exit(sys.version_info < (3, 9))\' 2>$null\n        if ($LASTEXITCODE -eq 0) {\n            $python = $candidate.Source\n            break\n        }\n    }\n}\nif (-not $python) {\n    $prefix = @()\n    $python = Join-Path $PSScriptRoot \'.python\\python.exe\'\n    if (-not (Test-Path $python)) {\n        Write-Host \'Downloading a private Python runtime...\'\n        New-Item -ItemType Directory -Force \'.downloads\' | Out-Null\n        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12\n        $installer = Join-Path $PSScriptRoot \'.downloads\\python-3.12.10-amd64.exe\'\n        Invoke-WebRequest \'https://www.python.org/ftp/python/3.12.10/python-3.12.10-amd64.exe\' -OutFile $installer -UseBasicParsing\n        $signature = Get-AuthenticodeSignature $installer\n        if ($signature.Status -ne \'Valid\' -or $signature.SignerCertificate.Subject -notmatch \'Python Software Foundation\') {\n            throw \'Python installer signature could not be verified.\'\n        }\n        $target = Join-Path $PSScriptRoot \'.python\'\n        $process = Start-Process -FilePath $installer -ArgumentList @(\'/quiet\', \'InstallAllUsers=0\', "TargetDir=`"$target`"", \'PrependPath=0\', \'Include_launcher=0\', \'Include_test=0\') -Wait -PassThru\n        if ($process.ExitCode -notin @(0, 3010)) { throw "Python installation failed: $($process.ExitCode)" }\n    }\n}\n& $python @prefix bootstrap.py @args\nexit $LASTEXITCODE\n'}
for name, content in FILES.items():
    path = ROOT / name
    if name.endswith('kyf37_resources.py') and path.exists() and 'def bundled_rom(' in path.read_text():
        continue
    if not path.exists() or path.read_text() != content:
        path.write_text(content)
p = ROOT / 'kyf37-installer/kyf37_installer.py'
s = p.read_text()
CHANGES = [('    raise SystemExit(\'adb not found. Install Android platform-tools and put adb on PATH, or unzip it to \'\n                     f\'{HERE / "platform-tools"}\')', "    from kyf37_resources import platform_tools\n    say('Downloading Android platform-tools from Google...')\n    return platform_tools(HERE / '.downloads')"), ("    rom = Path(args.rom) if args.rom else Path(ask('Path of the ROM installer ZIP (kyf37-android11-...-twrp.zip)'))", "    if args.rom:\n        rom = Path(args.rom).expanduser()\n    else:\n        from kyf37_resources import release_rom\n        say('Downloading the Android 11 ROM (verified downloads are cached)...')\n        rom = release_rom(HERE / '.downloads', args.rom_url, args.rom_sha256)"), ("    ap.add_argument('--rom', help='path to the ROM installer ZIP')", "    ap.add_argument('--rom', help='path to a local ROM installer ZIP (otherwise download)')\n    ap.add_argument('--rom-url', help='HTTPS ROM download URL')\n    ap.add_argument('--rom-sha256', help='published SHA-256 for --rom-url')")]
for old, new in CHANGES:
    if '# Bundled installer release layout v1' in s and ('adb not found' in old or '    rom = Path(args.rom)' in old):
        continue
    if new in s:
        continue
    if old not in s:
        raise RuntimeError('Installer source drift: ' + old[:80])
    s = s.replace(old, new)
p.write_text(s)

p = ROOT / 'kyf37-installer/README.md'
s = p.read_text()
s = s.replace('* Android platform-tools (`adb`) on your PATH, or unzipped to `kyf37-installer/platform-tools/`.', '* Android platform-tools are downloaded from Google automatically when ADB is missing. Existing ADB on PATH is reused.')
s = s.replace('* Python 3.9+ (the launcher creates a private `.venv` and installs `cryptography`, `pyusb`, `libusb-package`).', '* The launchers obtain Python when missing and maintain a private `.venv` with `cryptography`, `pyusb`, and `libusb-package`. Linux needs curl or wget and tar to obtain Python; automatic ADB downloads support x86-64 Linux and Windows. Other CPUs need a compatible ADB on PATH.')
s = s.replace('* The ROM installer ZIP (`kyf37-android11-…-twrp.zip`, about 650 MB). The script rebuilds it into', '* The ROM installer ZIP is downloaded from the latest GitHub release when a unique Android 11 TWRP asset with a published digest is available. You can supply `--rom FILE` or `--rom-url HTTPS_URL --rom-sha256 HASH` instead. The script rebuilds it into')
if '## Automatic downloads' not in s:
    s += """
## Automatic downloads

Start `./install.sh` on Linux or `./install.ps1` on Windows. Both default to dry run.
The launchers download missing Python and Python dependencies, then the installer obtains missing ADB.
Downloads live in `.downloads/`; private Python lives in `.python/`. Existing system Python and ADB are reused.
Interrupted downloads use temporary files. ROM files are reused only when their published SHA-256 matches.
No signing key is downloaded or uploaded.

Windows Python is obtained from python.org and its Authenticode signature is checked before installation.
Linux's fallback Python comes from the public python-build-standalone GitHub release; system Python is preferred.
Python packages and platform-tools are fetched over HTTPS from their upstream services.

If the latest ROM release does not publish the required Android 11 asset or its SHA-256, automatic ROM selection
stops. Supply a specific release URL and its trusted published digest, or a local ZIP. No Android 10 package is
silently selected. Windows diagnostic WinUSB setup still requires manual interface selection in Zadig; replacing
the wrong interface can disable ADB. Linux USB permissions may require an administrator to install the printed
udev rule. The installer does not change host drivers or privileged system configuration automatically.

Example: `./install.sh --rom-url https://example.org/kyf37-android11-twrp.zip --rom-sha256 PUBLISHED_HASH`
(replace the URL and hash with the actual release values).

Reapply the download sources with `python3 device-inspection/fix-kyf37-installer-downloads.py` after the two
resume/guard patch scripts. Offline tests cover Windows and Linux archive layouts. Native Windows execution and
end-to-end phone installation remain unverified.
"""
p.write_text(s)
p = ROOT / '.gitignore'
s = p.read_text()
for entry in ('kyf37-installer/.downloads/', 'kyf37-installer/.python/', 'kyf37-installer/platform-tools/'):
    if entry not in s.splitlines():
        s += '\n' + entry + '\n'
p.write_text(s)
